INSERT INTO dbo.faqs ([id],[question],[aliases_json],[answer],[conditions_json],[approved],[version],[source],[owner],[effective_from],[effective_to]) VALUES (N'FAQ-SHIP',N'Phí giao hàng',N'["giao hàng", "phí ship", "ship", "miễn phí"]',N'Chính sách DEMO: đơn từ 300.000đ được miễn phí giao hàng trong nội thành TP.HCM. Các trường hợp khác cần nhân viên xác nhận phí, chưa có thời gian giao cam kết.',N'{"region": "nội thành TP.HCM", "min_order_vnd": 300000}',1,N'demo-1',N'DEMO-POLICY',N'Demo fixture',N'2026-01-01T00:00:00+00:00',NULL);
INSERT INTO dbo.faqs ([id],[question],[aliases_json],[answer],[conditions_json],[approved],[version],[source],[owner],[effective_from],[effective_to]) VALUES (N'FAQ-RETURN',N'Đổi trả sản phẩm',N'["đổi trả", "đổi hàng", "hoàn tiền"]',N'Chính sách DEMO: tiếp nhận yêu cầu đổi hàng lỗi do nhà sản xuất trong 48 giờ sau nhận hàng, khi còn bao bì và bằng chứng mua hàng. Nhân viên kiểm tra trước khi xác nhận; không tự động duyệt hoàn tiền.',N'{}',1,N'demo-1',N'DEMO-POLICY',N'Demo fixture',N'2026-01-01T00:00:00+00:00',NULL);
INSERT INTO dbo.faqs ([id],[question],[aliases_json],[answer],[conditions_json],[approved],[version],[source],[owner],[effective_from],[effective_to]) VALUES (N'FAQ-STORAGE',N'Bảo quản bánh kẹo',N'["bảo quản"]',N'Chính sách DEMO: bảo quản nơi khô ráo, thoáng mát theo hướng dẫn trên nhãn từng sản phẩm. Không suy ra hạn dùng của lô hàng từ mô tả chung.',N'{}',1,N'demo-1',N'DEMO-POLICY',N'Demo fixture',N'2026-01-01T00:00:00+00:00',NULL);
INSERT INTO dbo.faqs ([id],[question],[aliases_json],[answer],[conditions_json],[approved],[version],[source],[owner],[effective_from],[effective_to]) VALUES (N'FAQ-HOURS',N'Giờ hỗ trợ',N'["giờ hỗ trợ", "mở cửa"]',N'Chính sách DEMO: hàng đợi được lưu trên máy local. Chưa có lịch trực hoặc thời gian phản hồi thực tế được shop xác nhận.',N'{}',1,N'demo-1',N'DEMO-POLICY',N'Demo fixture',N'2026-01-01T00:00:00+00:00',NULL);
